export type SpecTransitionResult = {
  /** The state the instance was in. */
  from: SpecState;
  /** The state it is in now. */
  to: SpecState;
};

/** The parameters of Revisions' listRevisions: Lists the instance's revisions, oldest first, one page at a time. */
export type SpecListRevisionsParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** At most this many revisions; 50 when absent. */
  limit?: number;
};

/** What Revisions' listRevisions returns. */
export type SpecListRevisionsResult = {
  items: Array<{
    /** When, in epoch milliseconds. */
    createdAt: number;
    /** The subject of the caller whose change it records. */
    createdBy: string;
    /** The instance's own fields as the change left them. */
    data: SpecFields;
    /** The proposal whose approval made it. */
    proposal?: number;
    /** Its number: 1, 2, 3, ... */
    revision: number;
  }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** The parameters of Revisions' getRevision: Reads one of the instance's revisions by its number: the own fields as that change left them. A number the instance has not reached is not_found. */
export type SpecGetRevisionParams = {
  /** The revision's number. */
  revision: number;
};

/** The revision. */
export type SpecGetRevisionResult = {
  /** When, in epoch milliseconds. */
  createdAt: number;
  /** The subject of the caller whose change it records. */
  createdBy: string;
  /** The instance's own fields as the change left them. */
  data: JSONObject;
  /** The proposal whose approval made it. */
  proposal?: number;
  /** Its number: 1, 2, 3, ... */
  revision: number;
};

/** The parameters of Revisions' propose: Proposes a change to the instance's own fields as a JSON merge patch, for a reviewer to approve or reject. The patch must change the instance and leave it valid; nothing changes until a reviewer approves it. */
export type SpecProposeParams = {
  /** Instances the proposal cites, for the reviewer: each one must exist and the proposer must be able to read its schema, and a revision must be one it has had, of a schema that composes Revisions. They are kept as given; a later change of an instance cited leaves them as they are. */
  evidence?: Array<{
    /** The instance's id. */
    id: string;
    /** The revision of it the proposal rests on. */
    revision?: number;
    /** The schema of the instance cited. */
    schema: string;
  }>;
  /** Why, for the reviewer. */
  note?: string;
  /** A JSON merge patch (RFC 7386) of the instance's own fields. */
  patch: SpecPatch;
};

/** The proposal. */
export type SpecProposeResult = {
  /** The instance's revision when it was proposed. */
  base?: number;
  createdAt: number;
  createdBy: string;
  /** The instances the proposal cites. */
  evidence?: Array<{ id: string; revision?: number; schema: string }>;
  /** The proposal's number on the instance: 1, 2, 3, ... */
  id: number;
  note?: string;
  patch: SpecPatch;
  reason?: string;
  reviewedAt?: number;
  reviewedBy?: string;
  revision?: number;
  state: 'pending' | 'approved' | 'rejected';
};

/** The parameters of Revisions' approve: Approves a pending proposal: applies its patch to the instance as an update, whose checks run, and records the revision it makes. Needs the review permission. */
export type SpecApproveParams = {
  /** The id of the pending proposal. */
  proposal: number;
};

/** The proposal, approved. */
export type SpecApproveResult = {
  base?: number;
  createdAt: number;
  createdBy: string;
  /** The instances the proposal cites. */
  evidence?: Array<{ id: string; revision?: number; schema: string }>;
  id: number;
  note?: string;
  patch: SpecPatch;
  reason?: string;
  reviewedAt?: number;
  reviewedBy?: string;
  /** The instance's revision after the approval. */
  revision?: number;
  state: 'pending' | 'approved' | 'rejected';
};

/** The parameters of Revisions' reject: Rejects a pending proposal; the instance does not change. Needs the review permission. */
export type SpecRejectParams = {
  /** The id of the pending proposal. */
  proposal: number;
  /** Why, for the proposer. */
  reason?: string;
};

/** The proposal, rejected. */
export type SpecRejectResult = {
  base?: number;
  createdAt: number;
  createdBy: string;
  /** The instances the proposal cites. */
  evidence?: Array<{ id: string; revision?: number; schema: string }>;
  id: number;
  note?: string;
  patch: SpecPatch;
  reason?: string;
  reviewedAt?: number;
  reviewedBy?: string;
  revision?: number;
  state: 'pending' | 'approved' | 'rejected';
};

/** The parameters of Revisions' listProposals: Lists the instance's proposals, oldest first, one page at a time; with state, only those in it. */
export type SpecListProposalsParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** At most this many proposals; 50 when absent. */
  limit?: number;
  /** Only proposals in this state. */
  state?: 'pending' | 'approved' | 'rejected';
};

/** What Revisions' listProposals returns. */
export type SpecListProposalsResult = {
  items: Array<{
    base?: number;
    createdAt: number;
    createdBy: string;
    evidence?: Array<{ id: string; revision?: number; schema: string }>;
    id: number;
    note?: string;
    patch: SpecPatch;
    reason?: string;
    reviewedAt?: number;
    reviewedBy?: string;
    revision?: number;
    state: 'pending' | 'approved' | 'rejected';
  }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** The parameters of Dependencies' addBlocker: Makes another instance block this one. It must be of the type's own schema or one the config lists, exist, and not be blocked by this instance, directly or through others. An instance in a gated state that is terminal takes no blocker that is not finished. */
export type SpecAddBlockerParams = {
  /** The blocker's id. */
  id: string;
  /** The blocker's schema. */
  schema: 'Task';
};

/** The blocker. */
export type SpecAddBlockerResult = {
  id: string;
  /** Whether it is not finished, so it blocks: its status is not a terminal state of its schema's Workflow whose outcome the config accepts. */
  open: boolean;
  schema: 'Task';
  /** The blocker's Workflow status. */
  status?: string;
};

/** The parameters of Dependencies' removeBlocker: Stops another instance from blocking this one. */
export type SpecRemoveBlockerParams = {
  /** The blocker's id. */
  id: string;
  /** The blocker's schema. */
  schema: 'Task';
};

/** The blocker removed. */
export type SpecRemoveBlockerResult = { id: string; schema: 'Task' };

/** The parameters of Dependencies' listBlockers: Lists the instance's blockers in the order they were added, one page at a time, with each one's status and whether it blocks. */
export type SpecListBlockersParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** At most this many blockers; 50 when absent. */
  limit?: number;
};

/** What Dependencies' listBlockers returns. */
export type SpecListBlockersResult = {
  items: Array<{
    id: string;
    /** Whether it is not finished, so it blocks: its status is not a terminal state of its schema's Workflow whose outcome the config accepts. */
    open: boolean;
    schema: 'Task';
    /** The blocker's Workflow status. */
    status?: string;
  }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** The parameters of Dependencies' listDependents: Lists the instances this one blocks, of every schema the caller may read, in the order they were added, one page at a time. */
export type SpecListDependentsParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** At most this many dependents; 50 when absent. A page holds fewer when the caller may not read some of their schemas. */
  limit?: number;
};

/** What Dependencies' listDependents returns. */
export type SpecListDependentsResult = {
  items: Array<{ id: string; schema: string }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** The parameters of Approvals' signOff: Signs off on the instance for a gated state, as the caller. Needs the gate's permission; refused for the instance's creator unless the gate allows it, while the instance is in the state, and for a caller whose sign-off for the state is not yet consumed. */
export type SpecSignOffParams = {
  /** Why, for the others. */
  note?: string;
  /** The gated state to sign off for. */
  state: 'final';
};

/** The sign-off, with the gate's sign-offs after it and the count it needs. */
export type SpecSignOffResult = {
  /** When, in epoch milliseconds. */
  at: number;
  /** How many the gate needs. */
  count: number;
  note?: string;
  /** Every subject whose sign-off for the state is not yet consumed, in the order they signed. */
  signedBy: string[];
  /** The gated state. */
  state: 'final';
  /** The subject of the caller who signed. */
  subject: string;
};

/** The parameters of Approvals' withdrawSignOff: Withdraws the caller's sign-off for a gated state, one not yet consumed. */
export type SpecWithdrawSignOffParams = {
  /** The gated state whose sign-off to withdraw. */
  state: 'final';
};

/** The sign-off withdrawn. */
export type SpecWithdrawSignOffResult = {
  /** When it was signed, in epoch milliseconds. */
  at: number;
  note?: string;
  /** The gated state. */
  state: 'final';
  /** The subject of the caller who signed. */
  subject: string;
};

/** The parameters of Approvals' listSignOffs: Lists the instance's sign-offs, oldest first, one page at a time, the consumed ones included; with state, only those for it. */
export type SpecListSignOffsParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** At most this many sign-offs; 50 when absent. */
  limit?: number;
  /** Only sign-offs for this state. */
  state?: string;
};

/** What Approvals' listSignOffs returns. */
export type SpecListSignOffsResult = {
  items: Array<{
    /** When, in epoch milliseconds. */
    at: number;
    /** When a change of the own fields, entering the state or a new version without its gate consumed it; absent while it counts. */
    consumedAt?: number;
    note?: string;
    /** The gated state. */
    state: string;
    /** The subject of the caller who signed. */
    subject: string;
  }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** Each operation a Spec's behaviors add: its scope, parameters and result. */
export type SpecOperations = {
  transition: { scope: 'instance'; params: SpecTransitionParams; result: SpecTransitionResult };
  listRevisions: { scope: 'instance'; params: SpecListRevisionsParams; result: SpecListRevisionsResult };
  getRevision: { scope: 'instance'; params: SpecGetRevisionParams; result: SpecGetRevisionResult };
  propose: { scope: 'instance'; params: SpecProposeParams; result: SpecProposeResult };
  approve: { scope: 'instance'; params: SpecApproveParams; result: SpecApproveResult };
  reject: { scope: 'instance'; params: SpecRejectParams; result: SpecRejectResult };
  listProposals: { scope: 'instance'; params: SpecListProposalsParams; result: SpecListProposalsResult };
  addBlocker: { scope: 'instance'; params: SpecAddBlockerParams; result: SpecAddBlockerResult };
  removeBlocker: { scope: 'instance'; params: SpecRemoveBlockerParams; result: SpecRemoveBlockerResult };
  listBlockers: { scope: 'instance'; params: SpecListBlockersParams; result: SpecListBlockersResult };
  listDependents: { scope: 'instance'; params: SpecListDependentsParams; result: SpecListDependentsResult };
  signOff: { scope: 'instance'; params: SpecSignOffParams; result: SpecSignOffResult };
  withdrawSignOff: { scope: 'instance'; params: SpecWithdrawSignOffParams; result: SpecWithdrawSignOffResult };
  listSignOffs: { scope: 'instance'; params: SpecListSignOffsParams; result: SpecListSignOffsResult };
};

/** The name of an operation on one Spec. */
export type SpecInstanceOperation = 'transition' | 'listRevisions' | 'getRevision' | 'propose' | 'approve' | 'reject' | 'listProposals' | 'addBlocker' | 'removeBlocker' | 'listBlockers' | 'listDependents' | 'signOff' | 'withdrawSignOff' | 'listSignOffs';

/** The codes the vetoes of a Spec's behaviors carry, by behavior: what a refused call's details.code holds. */
export type SpecVetoes = {
  Workflow: 'already_in_state' | 'terminal_state' | 'transition_not_allowed' | 'no_status';
  Revisions: 'no_review' | 'not_pending';
  Dependencies: 'blocked' | 'already_blocking' | 'cycle' | 'gated';
  Approvals: 'approvals_missing' | 'already_signed' | 'creator_cannot_sign' | 'in_state' | 'no_gate' | 'not_signed';
};

/** A Spec create's options: its id, and each behavior's create parameters. */
export type SpecCreateOptions = Omit<CreateOptions, 'behaviors'> & { readonly behaviors?: SpecCreateParams };

/** A Spec write's options: the sequence it expects, and each behavior's preconditions. */
export type SpecWriteOptions = Omit<WriteOptions, 'preconditions'>;

/** isSpecVeto is isVeto with the behaviors of a Spec and their codes. */
export function isSpecVeto<B extends keyof SpecVetoes>(error: unknown, behavior?: B, codes?: SpecVetoes[B] | ReadonlyArray<SpecVetoes[B]>): error is EngineVeto {
  return isVeto(error, behavior, codes);
}

/** The Spec schema's calls, typed: the engine's built-in operations, then each operation its behaviors add. */
export interface SpecClient {
  /** create stores a new Spec, with its behaviors' create parameters. */
  create(data: SpecFields, options?: SpecCreateOptions): Promise<Instance<Spec, SpecBehaviors>>;
  /** get reads a Spec; one that does not exist is 404 not_found. */
  get(id: string, options?: CallOptions): Promise<Instance<Spec, SpecBehaviors>>;
  /** list returns a page in creation order. */
  list(options?: ListOptions): Promise<InstancePage<Spec, SpecBehaviors>>;
  /** update applies a merge patch of the own fields. */
  update(id: string, patch: SpecPatch, options?: SpecWriteOptions): Promise<Instance<Spec, SpecBehaviors>>;
  /** delete removes a Spec. */
  delete(id: string, options?: SpecWriteOptions): Promise<void>;
  /** operate calls an instance operation and returns its result with the instance's sequence after it. */
  operate<K extends SpecInstanceOperation>(id: string, operation: K, params: SpecOperations[K]['params'], options?: SpecWriteOptions): Promise<OperationOutcome<SpecOperations[K]['result']>>;
  /** Workflow's transition: Moves the instance to another state along a transition the config lists. A transition that names a permission needs a caller who holds it. */
  transition(id: string, params: SpecTransitionParams, options?: SpecWriteOptions): Promise<SpecTransitionResult>;
  /** Revisions' listRevisions: Lists the instance's revisions, oldest first, one page at a time. */
  listRevisions(id: string, params?: SpecListRevisionsParams, options?: SpecWriteOptions): Promise<SpecListRevisionsResult>;
  /** Revisions' getRevision: Reads one of the instance's revisions by its number: the own fields as that change left them. A number the instance has not reached is not_found. */
  getRevision(id: string, params: SpecGetRevisionParams, options?: SpecWriteOptions): Promise<SpecGetRevisionResult>;
  /** Revisions' propose: Proposes a change to the instance's own fields as a JSON merge patch, for a reviewer to approve or reject. The patch must change the instance and leave it valid; nothing changes until a reviewer approves it. */
  propose(id: string, params: SpecProposeParams, options?: SpecWriteOptions): Promise<SpecProposeResult>;
  /** Revisions' approve: Approves a pending proposal: applies its patch to the instance as an update, whose checks run, and records the revision it makes. Needs the review permission. */
  approve(id: string, params: SpecApproveParams, options?: SpecWriteOptions): Promise<SpecApproveResult>;
  /** Revisions' reject: Rejects a pending proposal; the instance does not change. Needs the review permission. */
  reject(id: string, params: SpecRejectParams, options?: SpecWriteOptions): Promise<SpecRejectResult>;
  /** Revisions' listProposals: Lists the instance's proposals, oldest first, one page at a time; with state, only those in it. */
  listProposals(id: string, params?: SpecListProposalsParams, options?: SpecWriteOptions): Promise<SpecListProposalsResult>;
  /** Dependencies' addBlocker: Makes another instance block this one. It must be of the type's own schema or one the config lists, exist, and not be blocked by this instance, directly or through others. An instance in a gated state that is terminal takes no blocker that is not finished. */
  addBlocker(id: string, params: SpecAddBlockerParams, options?: SpecWriteOptions): Promise<SpecAddBlockerResult>;
  /** Dependencies' removeBlocker: Stops another instance from blocking this one. */
  removeBlocker(id: string, params: SpecRemoveBlockerParams, options?: SpecWriteOptions): Promise<SpecRemoveBlockerResult>;
  /** Dependencies' listBlockers: Lists the instance's blockers in the order they were added, one page at a time, with each one's status and whether it blocks. */
  listBlockers(id: string, params?: SpecListBlockersParams, options?: SpecWriteOptions): Promise<SpecListBlockersResult>;
  /** Dependencies' listDependents: Lists the instances this one blocks, of every schema the caller may read, in the order they were added, one page at a time. */
  listDependents(id: string, params?: SpecListDependentsParams, options?: SpecWriteOptions): Promise<SpecListDependentsResult>;
  /** Approvals' signOff: Signs off on the instance for a gated state, as the caller. Needs the gate's permission; refused for the instance's creator unless the gate allows it, while the instance is in the state, and for a caller whose sign-off for the state is not yet consumed. */
  signOff(id: string, params: SpecSignOffParams, options?: SpecWriteOptions): Promise<SpecSignOffResult>;
  /** Approvals' withdrawSignOff: Withdraws the caller's sign-off for a gated state, one not yet consumed. */
  withdrawSignOff(id: string, params: SpecWithdrawSignOffParams, options?: SpecWriteOptions): Promise<SpecWithdrawSignOffResult>;
  /** Approvals' listSignOffs: Lists the instance's sign-offs, oldest first, one page at a time, the consumed ones included; with state, only those for it. */
  listSignOffs(id: string, params?: SpecListSignOffsParams, options?: SpecWriteOptions): Promise<SpecListSignOffsResult>;
}

/** specClient wraps an EngineClient with the Spec schema's types. */
export function specClient(client: EngineClient): SpecClient {
  return {
    create(data, options) {
      return client.instances.create<Spec, SpecBehaviors>('Spec', data, options);
    },
    get(id, options) {
      return client.instances.get<Spec, SpecBehaviors>('Spec', id, options);
    },
    list(options) {
      return client.instances.list<Spec, SpecBehaviors>('Spec', options);
    },
    update(id, patch, options) {
      return client.instances.update<Spec, SpecBehaviors>('Spec', id, patch, options);
    },
    delete(id, options) {
      return client.instances.delete('Spec', id, options);
    },
    operate<K extends SpecInstanceOperation>(id: string, operation: K, params: SpecOperations[K]['params'], options?: SpecWriteOptions) {
      return client.instances.operate<SpecOperations[K]['result']>('Spec', id, operation, params, options);
    },
    transition(id, params, options) {
      return client.instances.invoke<SpecTransitionResult>('Spec', id, 'transition', params, options);
    },
    listRevisions(id, params, options) {
      return client.instances.invoke<SpecListRevisionsResult>('Spec', id, 'listRevisions', params ?? {}, options);
    },
    getRevision(id, params, options) {
      return client.instances.invoke<SpecGetRevisionResult>('Spec', id, 'getRevision', params, options);
    },
    propose(id, params, options) {
      return client.instances.invoke<SpecProposeResult>('Spec', id, 'propose', params, options);
    },
    approve(id, params, options) {
      return client.instances.invoke<SpecApproveResult>('Spec', id, 'approve', params, options);
    },
    reject(id, params, options) {
      return client.instances.invoke<SpecRejectResult>('Spec', id, 'reject', params, options);
    },
    listProposals(id, params, options) {
      return client.instances.invoke<SpecListProposalsResult>('Spec', id, 'listProposals', params ?? {}, options);
    },
    addBlocker(id, params, options) {
      return client.instances.invoke<SpecAddBlockerResult>('Spec', id, 'addBlocker', params, options);
    },
    removeBlocker(id, params, options) {
      return client.instances.invoke<SpecRemoveBlockerResult>('Spec', id, 'removeBlocker', params, options);
    },
    listBlockers(id, params, options) {
      return client.instances.invoke<SpecListBlockersResult>('Spec', id, 'listBlockers', params ?? {}, options);
    },
    listDependents(id, params, options) {
      return client.instances.invoke<SpecListDependentsResult>('Spec', id, 'listDependents', params ?? {}, options);
    },
    signOff(id, params, options) {
      return client.instances.invoke<SpecSignOffResult>('Spec', id, 'signOff', params, options);
    },
    withdrawSignOff(id, params, options) {
      return client.instances.invoke<SpecWithdrawSignOffResult>('Spec', id, 'withdrawSignOff', params, options);
    },
    listSignOffs(id, params, options) {
      return client.instances.invoke<SpecListSignOffsResult>('Spec', id, 'listSignOffs', params ?? {}, options);
    },
  };
}

// The Task schema.

export type Size = 'SMALL' | 'LARGE';

/** What a task is. */
export type TaskKind = 'build' | 'review' | 'chore';

/** Where the task's parts go. */
export type Box = {
  w: number;
  parts: Part[];
  inner?: Box | null;
};

/** What a build task builds. */
export type BuildDetail = {
  target: string;
  flags?: string[] | null;
};

export type Part = {
  name: string;
};

/** What a review task reviews. */
export type ReviewDetail = {
  pullRequest: number;
};

/** A Task's own fields, as a create gives them. A task of a project: its kind picks the shape of its detail, it pins the spec it builds, it lists the tasks it relates to, it waits for its blockers, and it fails a day after it starts unless it is done. */
export type TaskFields = {
  /** What the task does. */
  title: string;
  /** Hours. */
  estimate?: number | null;
  attempts?: number | null;
  due?: string | null;
  size?: Size | null;
  labels?: string[] | null;
  grid?: number[][] | null;
  box?: Box | null;
  meta?: JSONObject | null;
} & (
  | { kind: 'build'; detail?: BuildDetail | null }
  | { kind: 'review'; detail?: ReviewDetail | null }
  | { kind: 'chore'; detail?: null }
);

/** A Task's data as a read returns it: its own fields. Its behaviors' fields are in TaskBehaviors. */
export type Task = TaskFields;

/** The fields of a Task's behaviors as a read returns them, by behavior name: each behavior that declares a field, with those of its fields that have a value. */
export type TaskBehaviors = {
  readonly Workflow: {
    /** The state the instance is in. */
    readonly status: TaskState;
    /** When the status last changed, in epoch milliseconds: the create's time, then each transition's. Absent on an instance created before Workflow kept it, until its next transition. */
    readonly enteredAt?: number;
  };
  readonly Comments: {
    /** How many comments the instance has. */
    readonly commentCount: number;
  };
  readonly Links: {
    /** The links the instance holds, by name: each target's schema and id, and for a pinned link the revision or the release it records, the target's latest and whether the target has moved past it; for a many-valued link, a list of them in the order they were linked. Absent when the instance holds none. */
    readonly targets: {
      /** The Task instance parent points at. */
      parent?: { id: string; schema: 'Task' };
      /** The Project instance project points at. */
      project: { id: string; schema: 'Project' };
      /** The Task instances related points at, in the order they were linked. */
      related?: Array<{ id: string; schema: 'Task' }>;
      /** The Spec instance spec points at. */
      spec?: {
        id: string;
        /** The target's latest revision. */
        latest?: number;
        /** The target's revision the link records. */
        revision?: number;
        schema: 'Spec';
        /** Whether the target has moved past that revision. */
        stale?: boolean;
      };
    };
  };
  readonly Numbering: {
    /** The instance's number in its count, from 1; absent until it is numbered. */
    readonly seq?: number;
    /** The number as the format prints it, unique within its scope; absent until it is numbered. */
    readonly label?: string;
  };
  readonly Timers: {
    /** Each started deadline, by name: { dueAt, fired, firedAt?, outcome? }, when it is due, in epoch milliseconds, whether it has fired and when, and what its then met: moved, skipped (the status was not one it moves from), vetoed or forbidden. A deadline not started, or cancelled, is absent. Nothing in it follows the clock: a deadline is overdue while it has not fired and its dueAt has passed. */
    readonly deadlines: {
      overdue?: {
        dueAt: number;
        fired: boolean;
        firedAt?: number;
        outcome?: 'moved' | 'skipped' | 'vetoed' | 'forbidden';
      };
      stuck?: {
        dueAt: number;
        fired: boolean;
        firedAt?: number;
        outcome?: 'moved' | 'skipped' | 'vetoed' | 'forbidden';
      };
    };
  };
  readonly Dependencies: {
    /** Whether a blocker is not finished: its status is not a terminal state of its schema's Workflow whose outcome the config accepts. */
    readonly blocked: boolean;
  };
};

/** A merge patch of a Task's own fields (RFC 7386): null removes an optional field. Its behaviors' fields change through their operations. */
export type TaskPatch = {
  /** What the task does. */
  title?: string;
  /** What the task is. */
  kind?: TaskKind;
  /** Hours. */
  estimate?: number | null;
  attempts?: number | null;
  due?: string | null;
  size?: Size | null;
  labels?: string[] | null;
  grid?: number[][] | null;
  box?: Box | null;
  meta?: JSONObject | null;
  /** The task's detail, of its kind's type. */
  detail?: BuildDetail | ReviewDetail | null;
};

/** A state of a Task's Workflow. */
export type TaskState = 'todo' | 'doing' | 'done' | 'failed';

/** A link of a Task, by name. */
export type TaskLinkName = 'parent' | 'project' | 'related' | 'spec';

/** The parameters a Task's create gives its behaviors, by behavior name. */
export type TaskCreateParams = {
  Dependencies?: {
    /** The instance's blockers from its create, each held to addBlocker's rules. */
    blockers?: Array<{
      /** The blocker's id. */
      id: string;
      /** The blocker's schema; Task when absent. */
      schema?: 'Task' | 'Spec';
    }>;
  };
  /** The links the instance holds from its create, by name, each held to link's rules. */
  Links: {
    /** The Task instance parent points at: its id. */
    parent?: string | {
      /** The target's id. */
      id: string;
    };
    /** The Project instance project points at: its id. */
    project: string | {
      /** The target's id. */
      id: string;
    };
    /** The Task instances related points at, in order, each once. */
    related?: Array<string | {
      /** The target's id. */
      id: string;
    }>;
    /** The Spec instance spec points at: its id, or an object with its id and the revision to record. */
    spec?: string | {
      /** The target's id. */
      id: string;
      /** The target's revision to record, one it has had; its latest when absent. */
      revision?: number;
    };
  };
};

/** The parameters of Workflow's transition: Moves the instance to another state along a transition the config lists. A transition that names a permission needs a caller who holds it. */
export type TaskTransitionParams = {
  /** The state to move to. */
  to: TaskState;
};

/** What Workflow's transition returns. */
export type TaskTransitionResult = {
  /** The state the instance was in. */
  from: TaskState;
  /** The state it is in now. */
  to: TaskState;
};

/** The parameters of Comments' comment: Adds a comment to the instance, or a reply to one of its comments. */
export type TaskCommentParams = {
  /** The comment's text. */
  body: string;
  /** The id of the instance's comment this one replies to. */
  replyTo?: number;
};

/** The comment. */
export type TaskCommentResult = {
  body: string;
  /** When, in epoch milliseconds. */
  createdAt: number;
  /** The subject of the caller who added it. */
  createdBy: string;
  /** The comment's number on the instance: 1, 2, 3, ... */
  id: number;
  /** The id of the comment it replies to. */
  replyTo?: number;
};

/** The parameters of Comments' listComments: Lists the instance's comments, oldest first, one page at a time. */
export type TaskListCommentsParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** At most this many comments; 50 when absent. */
  limit?: number;
};

/** What Comments' listComments returns. */
export type TaskListCommentsResult = {
  items: Array<{
    body: string;
    createdAt: number;
    createdBy: string;
    id: number;
    replyTo?: number;
  }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** The parameters of Links' link: Points a link at an instance of its schema, replacing the target it had; a many-valued link adds the instance to its list, or pins again one it holds. A pinned link records the target's latest revision or release, or the one given. */
export type TaskLinkParams = {
  /** The target's id. */
  id: string;
  /** The link's name in the config. */
  name: TaskLinkName;
  /** For a link pinned to a release, the target's release to record, one it has had; its latest when absent. */
  release?: number;
  /** For a link pinned to a revision, the target's revision to record, one it has had; its latest when absent. */
  revision?: number;
};

/** The link. */
export type TaskLinkResult = {
  id: string;
  name: TaskLinkName;
  /** The target's release a link pinned to a release records. */
  release?: number;
  /** The target's revision a link pinned to a revision records. */
  revision?: number;
  schema: string;
};

/** The parameters of Links' unlink: Clears an optional link, or removes one target of a many-valued link. A required link cannot be unlinked, only moved, and a required many-valued link keeps at least one target. */
export type TaskUnlinkParams = {
  /** The target to remove, which a many-valued link needs; for a link that holds one target, the one it must hold. */
  id?: string;
  /** The link's name in the config. */
  name: TaskLinkName;
};

/** The link as it was. */
export type TaskUnlinkResult = {
  id: string;
  name: TaskLinkName;
  release?: number;
  revision?: number;
  schema: string;
};

/** The parameters of Links' listLinked: Lists the instances of this schema whose link points at an instance, in the order the links were made, one page at a time; for a pinned link, with the revision or the release each records, the target's latest and whether the target has moved past it. */
export type TaskListLinkedParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** The target's id. */
  id: string;
  /** At most this many instances; 50 when absent. */
  limit?: number;
  /** The link's name in the config. */
  name: TaskLinkName;
  /** Only the pinned links whose target has moved past the revision or the release they record. */
  stale?: boolean;
};

/** What Links' listLinked returns. */
export type TaskListLinkedResult = {
  items: Array<{
    /** The id of the instance that holds the link. */
    id: string;
    /** The target's latest revision or release, of the kind the link pins. */
    latest?: number;
    /** The target's release a link pinned to a release records. */
    release?: number;
    /** The target's revision a link pinned to a revision records. */
    revision?: number;
    /** Whether the target has moved past the one the link records. */
    stale?: boolean;
  }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** The parameters of Numbering's assignNumber: Numbers an instance created before its schema composed Numbering, in the count of the year it was created in, as its create would have. On an instance numbered already it changes nothing and returns its number. A deployment backfills by invoking it in creation order. */
export type TaskAssignNumberParams = Record<string, never>;

/** The instance's number. */
export type TaskAssignNumberResult = {
  /** The number as the format prints it. */
  label: string;
  /** Its number in its count. */
  seq: number;
};

/** The parameters of Timers' fireTimer: Fires a deadline that is due and has not fired: marks it fired and moves the status by its then, recording the outcome; a veto or a missing permission the move meets leaves the status as it is and the deadline fired. A deadline whose until holds is cancelled instead. On a deadline not due, fired already or not started it changes nothing. Any principal who may write the instance may call it; the engine's runner calls it on every due deadline, every sweepMs. */
export type TaskFireTimerParams = {
  /** The deadline's name. */
  deadline: 'overdue' | 'stuck';
};

/** What Timers' fireTimer returns. */
export type TaskFireTimerResult = {
  /** Whether this call fired the deadline. */
  fired: boolean;
  /** When it fired a deadline with then: what the move met. */
  outcome?: 'moved' | 'skipped' | 'vetoed' | 'forbidden';
};

/** The parameters of Timers' resetTimer: Starts a deadline again from what it starts from now, the create, the status's entry into its state or its field's value, so it is due afterMs after it and not fired: a snooze or a fire is undone. Needs the config's permission; refused for a deadline with nothing to start from now, or whose until holds. */
export type TaskResetTimerParams = {
  /** The deadline's name. */
  deadline: 'overdue' | 'stuck';
};

/** What Timers' resetTimer returns. */
export type TaskResetTimerResult = {
  /** When it is due, in epoch milliseconds. */
  dueAt: number;
};

/** The parameters of Timers' snoozeTimer: Moves a started deadline's due time to dueAt, and a fired one fires again then. A later write keeps it, until what the deadline starts from changes. Needs the config's permission; refused for a deadline not started, cancelled, or whose until holds. */
export type TaskSnoozeTimerParams = {
  /** The deadline's name. */
  deadline: 'overdue' | 'stuck';
  /** When it is due, in epoch milliseconds. */
  dueAt: number;
};

/** What Timers' snoozeTimer returns. */
export type TaskSnoozeTimerResult = {
  /** When it is due, in epoch milliseconds. */
  dueAt: number;
};

/** The parameters of Dependencies' addBlocker: Makes another instance block this one. It must be of the type's own schema or one the config lists, exist, and not be blocked by this instance, directly or through others. An instance in a gated state that is terminal takes no blocker that is not finished. */
export type TaskAddBlockerParams = {
  /** The blocker's id. */
  id: string;
  /** The blocker's schema; Task when absent. */
  schema?: 'Task' | 'Spec';
};

/** The blocker. */
export type TaskAddBlockerResult = {
  id: string;
  /** Whether it is not finished, so it blocks: its status is not a terminal state of its schema's Workflow whose outcome the config accepts. */
  open: boolean;
  schema: 'Task' | 'Spec';
  /** The blocker's Workflow status. */
  status?: string;
};

/** The parameters of Dependencies' removeBlocker: Stops another instance from blocking this one. */
export type TaskRemoveBlockerParams = {
  /** The blocker's id. */
  id: string;
  /** The blocker's schema; Task when absent. */
  schema?: 'Task' | 'Spec';
};

/** The blocker removed. */
export type TaskRemoveBlockerResult = { id: string; schema: 'Task' | 'Spec' };

/** The parameters of Dependencies' listBlockers: Lists the instance's blockers in the order they were added, one page at a time, with each one's status and whether it blocks. */
export type TaskListBlockersParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** At most this many blockers; 50 when absent. */
  limit?: number;
};

/** What Dependencies' listBlockers returns. */
export type TaskListBlockersResult = {
  items: Array<{
    id: string;
    /** Whether it is not finished, so it blocks: its status is not a terminal state of its schema's Workflow whose outcome the config accepts. */
    open: boolean;
    schema: 'Task' | 'Spec';
    /** The blocker's Workflow status. */
    status?: string;
  }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** The parameters of Dependencies' listDependents: Lists the instances this one blocks, of every schema the caller may read, in the order they were added, one page at a time. */
export type TaskListDependentsParams = {
  /** The next of the previous page. */
  cursor?: string;
  /** At most this many dependents; 50 when absent. A page holds fewer when the caller may not read some of their schemas. */
  limit?: number;
};

/** What Dependencies' listDependents returns. */
export type TaskListDependentsResult = {
  items: Array<{ id: string; schema: string }>;
  /** The cursor of the next page; null after the last. */
  next: string | null;
};

/** Each operation a Task's behaviors add: its scope, parameters and result. */
export type TaskOperations = {
  transition: { scope: 'instance'; params: TaskTransitionParams; result: TaskTransitionResult };
  comment: { scope: 'instance'; params: TaskCommentParams; result: TaskCommentResult };
  listComments: { scope: 'instance'; params: TaskListCommentsParams; result: TaskListCommentsResult };
  link: { scope: 'instance'; params: TaskLinkParams; result: TaskLinkResult };
  unlink: { scope: 'instance'; params: TaskUnlinkParams; result: TaskUnlinkResult };
  listLinked: { scope: 'schema'; params: TaskListLinkedParams; result: TaskListLinkedResult };
  assignNumber: { scope: 'instance'; params: TaskAssignNumberParams; result: TaskAssignNumberResult };
  fireTimer: { scope: 'instance'; params: TaskFireTimerParams; result: TaskFireTimerResult };
  resetTimer: { scope: 'instance'; params: TaskResetTimerParams; result: TaskResetTimerResult };
  snoozeTimer: { scope: 'instance'; params: TaskSnoozeTimerParams; result: TaskSnoozeTimerResult };
  addBlocker: { scope: 'instance'; params: TaskAddBlockerParams; result: TaskAddBlockerResult };
  removeBlocker: { scope: 'instance'; params: TaskRemoveBlockerParams; result: TaskRemoveBlockerResult };
  listBlockers: { scope: 'instance'; params: TaskListBlockersParams; result: TaskListBlockersResult };
  listDependents: { scope: 'instance'; params: TaskListDependentsParams; result: TaskListDependentsResult };
};

/** The name of an operation on one Task. */
export type TaskInstanceOperation = 'transition' | 'comment' | 'listComments' | 'link' | 'unlink' | 'assignNumber' | 'fireTimer' | 'resetTimer' | 'snoozeTimer' | 'addBlocker' | 'removeBlocker' | 'listBlockers' | 'listDependents';

/** The codes the vetoes of a Task's behaviors carry, by behavior: what a refused call's details.code holds. */
export type TaskVetoes = {
  Workflow: 'already_in_state' | 'terminal_state' | 'transition_not_allowed' | 'no_status';
  Comments: never;
  Links: 'no_revision' | 'no_release' | 'required_link' | 'required_target' | 'too_many' | 'not_linked';
  Numbering: never;
  Timers: 'no_deadline' | 'not_armed';
  Dependencies: 'blocked' | 'already_blocking' | 'cycle' | 'gated';
  Constants: never;
  Variants: never;
};

/** A Task create's options: its id, and each behavior's create parameters. */
export type TaskCreateOptions = Omit<CreateOptions, 'behaviors'> & { readonly behaviors: TaskCreateParams };

/** A Task write's options: the sequence it expects, and each behavior's preconditions. */
export type TaskWriteOptions = Omit<WriteOptions, 'preconditions'>;

/** isTaskVeto is isVeto with the behaviors of a Task and their codes. */
export function isTaskVeto<B extends keyof TaskVetoes>(error: unknown, behavior?: B, codes?: TaskVetoes[B] | ReadonlyArray<TaskVetoes[B]>): error is EngineVeto {
  return isVeto(error, behavior, codes);
}

/** The Task schema's calls, typed: the engine's built-in operations, then each operation its behaviors add. */
export interface TaskClient {
  /** create stores a new Task, with its behaviors' create parameters. */
  create(data: TaskFields, options: TaskCreateOptions): Promise<Instance<Task, TaskBehaviors>>;
  /** get reads a Task; one that does not exist is 404 not_found. */
  get(id: string, options?: CallOptions): Promise<Instance<Task, TaskBehaviors>>;
  /** list returns a page in creation order. */
  list(options?: ListOptions): Promise<InstancePage<Task, TaskBehaviors>>;
  /** update applies a merge patch of the own fields. */
  update(id: string, patch: TaskPatch, options?: TaskWriteOptions): Promise<Instance<Task, TaskBehaviors>>;
  /** delete removes a Task. */
  delete(id: string, options?: TaskWriteOptions): Promise<void>;
  /** operate calls an instance operation and returns its result with the instance's sequence after it. */
  operate<K extends TaskInstanceOperation>(id: string, operation: K, params: TaskOperations[K]['params'], options?: TaskWriteOptions): Promise<OperationOutcome<TaskOperations[K]['result']>>;
  /** Workflow's transition: Moves the instance to another state along a transition the config lists. A transition that names a permission needs a caller who holds it. */
  transition(id: string, params: TaskTransitionParams, options?: TaskWriteOptions): Promise<TaskTransitionResult>;
  /** Comments' comment: Adds a comment to the instance, or a reply to one of its comments. */
  comment(id: string, params: TaskCommentParams, options?: TaskWriteOptions): Promise<TaskCommentResult>;
  /** Comments' listComments: Lists the instance's comments, oldest first, one page at a time. */
  listComments(id: string, params?: TaskListCommentsParams, options?: TaskWriteOptions): Promise<TaskListCommentsResult>;
  /** Links' link: Points a link at an instance of its schema, replacing the target it had; a many-valued link adds the instance to its list, or pins again one it holds. A pinned link records the target's latest revision or release, or the one given. */
  link(id: string, params: TaskLinkParams, options?: TaskWriteOptions): Promise<TaskLinkResult>;
  /** Links' unlink: Clears an optional link, or removes one target of a many-valued link. A required link cannot be unlinked, only moved, and a required many-valued link keeps at least one target. */
  unlink(id: string, params: TaskUnlinkParams, options?: TaskWriteOptions): Promise<TaskUnlinkResult>;
  /** Links' listLinked: Lists the instances of this schema whose link points at an instance, in the order the links were made, one page at a time; for a pinned link, with the revision or the release each records, the target's latest and whether the target has moved past it. */
  listLinked(params: TaskListLinkedParams, options?: CallOptions): Promise<TaskListLinkedResult>;
  /** Numbering's assignNumber: Numbers an instance created before its schema composed Numbering, in the count of the year it was created in, as its create would have. On an instance numbered already it changes nothing and returns its number. A deployment backfills by invoking it in creation order. */
  assignNumber(id: string, params?: TaskAssignNumberParams, options?: TaskWriteOptions): Promise<TaskAssignNumberResult>;
  /** Timers' fireTimer: Fires a deadline that is due and has not fired: marks it fired and moves the status by its then, recording the outcome; a veto or a missing permission the move meets leaves the status as it is and the deadline fired. A deadline whose until holds is cancelled instead. On a deadline not due, fired already or not started it changes nothing. Any principal who may write the instance may call it; the engine's runner calls it on every due deadline, every sweepMs. */
  fireTimer(id: string, params: TaskFireTimerParams, options?: TaskWriteOptions): Promise<TaskFireTimerResult>;
  /** Timers' resetTimer: Starts a deadline again from what it starts from now, the create, the status's entry into its state or its field's value, so it is due afterMs after it and not fired: a snooze or a fire is undone. Needs the config's permission; refused for a deadline with nothing to start from now, or whose until holds. */
  resetTimer(id: string, params: TaskResetTimerParams, options?: TaskWriteOptions): Promise<TaskResetTimerResult>;
  /** Timers' snoozeTimer: Moves a started deadline's due time to dueAt, and a fired one fires again then. A later write keeps it, until what the deadline starts from changes. Needs the config's permission; refused for a deadline not started, cancelled, or whose until holds. */
  snoozeTimer(id: string, params: TaskSnoozeTimerParams, options?: TaskWriteOptions): Promise<TaskSnoozeTimerResult>;
  /** Dependencies' addBlocker: Makes another instance block this one. It must be of the type's own schema or one the config lists, exist, and not be blocked by this instance, directly or through others. An instance in a gated state that is terminal takes no blocker that is not finished. */
  addBlocker(id: string, params: TaskAddBlockerParams, options?: TaskWriteOptions): Promise<TaskAddBlockerResult>;
  /** Dependencies' removeBlocker: Stops another instance from blocking this one. */
  removeBlocker(id: string, params: TaskRemoveBlockerParams, options?: TaskWriteOptions): Promise<TaskRemoveBlockerResult>;
  /** Dependencies' listBlockers: Lists the instance's blockers in the order they were added, one page at a time, with each one's status and whether it blocks. */
  listBlockers(id: string, params?: TaskListBlockersParams, options?: TaskWriteOptions): Promise<TaskListBlockersResult>;
  /** Dependencies' listDependents: Lists the instances this one blocks, of every schema the caller may read, in the order they were added, one page at a time. */
  listDependents(id: string, params?: TaskListDependentsParams, options?: TaskWriteOptions): Promise<TaskListDependentsResult>;
}

/** taskClient wraps an EngineClient with the Task schema's types. */
export function taskClient(client: EngineClient): TaskClient {
  return {
    create(data, options) {
      return client.instances.create<Task, TaskBehaviors>('Task', data, options);
    },
    get(id, options) {
      return client.instances.get<Task, TaskBehaviors>('Task', id, options);
    },
    list(options) {
      return client.instances.list<Task, TaskBehaviors>('Task', options);
    },
    update(id, patch, options) {
      return client.instances.update<Task, TaskBehaviors>('Task', id, patch, options);
    },
    delete(id, options) {
      return client.instances.delete('Task', id, options);
    },
    operate<K extends TaskInstanceOperation>(id: string, operation: K, params: TaskOperations[K]['params'], options?: TaskWriteOptions) {
      return client.instances.operate<TaskOperations[K]['result']>('Task', id, operation, params, options);
    },
    transition(id, params, options) {
      return client.instances.invoke<TaskTransitionResult>('Task', id, 'transition', params, options);
    },
    comment(id, params, options) {
      return client.instances.invoke<TaskCommentResult>('Task', id, 'comment', params, options);
    },
    listComments(id, params, options) {
      return client.instances.invoke<TaskListCommentsResult>('Task', id, 'listComments', params ?? {}, options);
    },
    link(id, params, options) {
      return client.instances.invoke<TaskLinkResult>('Task', id, 'link', params, options);
    },
    unlink(id, params, options) {
      return client.instances.invoke<TaskUnlinkResult>('Task', id, 'unlink', params, options);
    },
    listLinked(params, options) {
      return client.instances.invokeSchema<TaskListLinkedResult>('Task', 'listLinked', params, options);
    },
    assignNumber(id, params, options) {
      return client.instances.invoke<TaskAssignNumberResult>('Task', id, 'assignNumber', params ?? {}, options);
    },
    fireTimer(id, params, options) {
      return client.instances.invoke<TaskFireTimerResult>('Task', id, 'fireTimer', params, options);
    },
    resetTimer(id, params, options) {
      return client.instances.invoke<TaskResetTimerResult>('Task', id, 'resetTimer', params, options);
    },
    snoozeTimer(id, params, options) {
      return client.instances.invoke<TaskSnoozeTimerResult>('Task', id, 'snoozeTimer', params, options);
    },
    addBlocker(id, params, options) {
      return client.instances.invoke<TaskAddBlockerResult>('Task', id, 'addBlocker', params, options);
    },
    removeBlocker(id, params, options) {
      return client.instances.invoke<TaskRemoveBlockerResult>('Task', id, 'removeBlocker', params, options);
    },
    listBlockers(id, params, options) {
      return client.instances.invoke<TaskListBlockersResult>('Task', id, 'listBlockers', params ?? {}, options);
    },
    listDependents(id, params, options) {
      return client.instances.invoke<TaskListDependentsResult>('Task', id, 'listDependents', params ?? {}, options);
    },
  };
}
